use hec_native_ic::fp::Fp;
#[derive(Clone,Debug)]pub struct Proof{pub excluded:bool,pub k:u64,pub w:Vec<u64>}
pub fn prove(rows:&[(Vec<u64>,u64)],n:usize,f:&Fp)->Proof{let mut basis:Vec<Option<(Vec<u64>,Vec<u64>)>>=vec![None;n];for(i,(v,b))in rows.iter().enumerate(){let mut a=v.clone();a.push(*b);let mut w=vec![0;rows.len()];w[i]=1;for j in 0..n{if a[j]==0{continue}if let Some((q,z))=&basis[j]{let scale=a[j];for k in j..=n{a[k]=f.sub(a[k],f.mul(scale,q[k]));}for k in 0..w.len(){w[k]=f.sub(w[k],f.mul(scale,z[k]));}}else{let iv=f.inv(a[j]);for x in &mut a{*x=f.mul(*x,iv);}for x in &mut w{*x=f.mul(*x,iv);}basis[j]=Some((a.clone(),w.clone()));break}}
if a[..n].iter().all(|x|*x==0)&&a[n]!=0{let iv=f.inv(a[n]);for x in &mut w{*x=f.mul(*x,iv);}return Proof{excluded:true,k:1,w}}}let(a,w)=basis[n-1].as_ref().expect("unresolved branch");Proof{excluded:false,k:a[n],w:w.clone()}}
pub fn verify(rows:&[(Vec<u64>,u64)],n:usize,f:&Fp,p:&Proof)->bool{if p.w.len()!=rows.len()||p.w.iter().any(|x|*x>=f.p)||p.k>=f.p{return false}let mut sum=vec![0;n];let mut rhs=0;for((a,b),&w)in rows.iter().zip(&p.w){for j in 0..n{sum[j]=f.add(sum[j],f.mul(w,a[j]));}rhs=f.add(rhs,f.mul(w,*b));}if p.excluded{sum.iter().all(|x|*x==0)&&rhs==1&&p.k==1}else{let mut e=vec![0;n];e[n-1]=1;sum==e&&rhs==p.k}}
